<template><BioNexusDialog ref="box" size="fullscreen" kicker="Ajustar precios" title="Vista previa de cambios"><section class="preview-body"><div class="preview-summary"><strong>{{ rows.length }} cambio(s) calculado(s)</strong><span>Revisa los valores antes de regresar y aplicar el ajuste.</span></div><BioNexusDataGrid :row-data="rows" :column-defs="columns" :get-row-id="getId" :search-enabled="true" v-model:search-model-value="search" search-placeholder="Buscar cambio" :export-options="exportOptions" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="420" :max-grid-height="680" /></section><template #footer><button type="button" class="bio-nexus-action bio-nexus-action-primary" @click="close">Volver al ajuste</button></template></BioNexusDialog></template>
<script setup>import{computed,ref}from"vue";import BioNexusDataGrid from"@/components/grid/BioNexusDataGrid.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import{formatUsdPrice}from"@/services/regionalFormatter";import{useRegionalSettingsStore}from"@/stores/regionalSettings";const settings=useRegionalSettingsStore(),box=ref(null),rows=ref([]),operation=ref("increase"),search=ref(""),exportOptions=Object.freeze({fileName:"ajuste-precios-vista-previa",title:"Vista previa de ajuste de precios",excludeColumns:[]});const columns=computed(()=>[{field:"group_description",headerName:"Grupo",minWidth:220,flex:1},{field:"exam",headerName:"Examen",minWidth:280,flex:1.4},{field:"tariff",headerName:"Tarifa",minWidth:160,flex:.8},{field:"current",headerName:"Precio actual",minWidth:150,valueFormatter:p=>formatUsdPrice(p.value,settings.settings)},{field:"variation",headerName:"Variación",minWidth:150,valueFormatter:p=>(operation.value==="increase"?"+":"-")+formatUsdPrice(p.value,settings.settings)},{field:"result",headerName:"Precio resultante",minWidth:180,valueFormatter:p=>formatUsdPrice(p.value,settings.settings)}]);function getId({data}){return data.id}function open(values,type){rows.value=values||[];operation.value=type||"increase";search.value="";box.value?.open()}function close(){box.value?.close()}defineExpose({open});</script>
<style scoped>.preview-body{display:grid;gap:12px;width:100%;min-width:0;padding:14px}.preview-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 12px;border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-info-soft);color:var(--bio-nexus-color-text-secondary)}.preview-body :deep(.bio-nexus-data-grid){width:100%;min-width:0}</style>
